-- D3: world-map icons for the doors of Forever's instances (data only: one row = one icon; Labels.lua draws it like every
-- entrance, Dungeon.lua opens the map on a click).
--   c = the map the door is on (0 Eastern Kingdoms, 1 Kalimdor), x / y = its world position (north / west yards),
--   zone = the uiMap it lies in (a check: the harness places the icon there), label = the name on the world map (also
--   the entrance key), d = the instance it leads to, floor = the floor to open, note = a tooltip line,
--   conf = (1.0.0) "medium": the tooltip says the door is not confirmed yet, and a door the addon learns in game
--   (Doors.lua) moves the icon there; rows without conf, and "high" ones, are never moved.
-- Sources (the door research, tools/doors; local client 1.60.1.70124 read-only; world X north, Y west): see each row.
-- Ruins of Lordaeron: a Forever-era portal swirl (model 197007, placement uid 65,746,533) at Tirisfal Glades 63.3, 67.5 with
-- its exit swirl 15.9 yd away inside map 2999 (verify_inventory: positions confirmed, confidence medium-high; that it
-- leads to 2999 is inferred from the pair).
-- The Hall of Thanes (1.0.0): confirmed IN GAME - at its door C_Map.GetBestMapForUnit = 1455 and UnitPosition = -4821,
-- -937.6 (Ironforge 28.33, 47.72; Dun Morogh 55.63, 28.75; the zone texts say "Ironforge" there, "The Hall of Thanes"
-- inside). The point lies on the floor of the Ironforge WMO's (fileDataID 7801267) MOGP group 'throneRoom' (groupID
-- 83348, a WMOAreaTable row without a name, so the game says "Ironforge"), west of the Great Forge, behind the High Seat.
-- Excavation Site: Wetlands (1.0.0, high): 2998's own entrance swirl (placement uid 67570010) sits on this spot - the
-- instance copies the Wetlands terrain at unchanged coordinates - on terrain area 17732 'Excavation Site: Wetlands';
-- two web guides agree within 7 yd (foreverchanges 47.8, 56.3; wowhandbook 47.9, 56.5). The Dun Morogh tunnel swirl at
-- Wetlands 24.4, 73.4 is NOT this door (it is unattributed).
-- City of Dalaran (1.0.0, medium, unconfirmed): Dalaran itself is the OPEN-WORLD city of Eastern Kingdoms (map 0,
-- Alterac Mountains; drawn into the world map by DetailMaps.lua, never linked to the 2959 pages), but the City of
-- Dalaran DUNGEON (2959) has its door in the city's sewers: the purple swirl at the end of the long pipe (doodad 3909 of
-- Dalaran WMO 7116370, group 'exitPipe', area 'Sewer'; the web: "follows a long pipe to a purple portal"). The other
-- candidate is the swirl in the Underbelly (224.2, 176.4 = Alterac 21.7, 68.4, group 'shadeyDealer'): both are hints
-- in ns.FOREVER_DOOR_HINTS below, so a door learned at either one (Doors.lua) confirms it.
-- Not added: Half-Pint Tavern (3002) - no door in the client data; a door learned in game adds its icon (Doors.lua).
ns.FOREVER_DOORS = {
  { c = 0, x = 1804.2, y = 175.0, zone = 1420, label = "Ruins of Lordaeron (portal)", d = 2999, floor = 1, note = "Portal in the ruins above the Undercity" },
  { c = 0, x = -4821.0, y = -937.6, zone = 1455, label = "The Hall of Thanes", d = 3065, floor = 1, note = "Door west of the Great Forge, behind the High Seat" },
  { c = 0, x = -3704.1, y = -2371.2, zone = 1437, label = "Excavation Site: Wetlands", d = 2998, floor = 1, note = "Blue mist under a large tree", conf = "high" },
  { c = 0, x = 376.9, y = 524.8, zone = 1416, label = "City of Dalaran", d = 2959, floor = 1, note = "Portal at the end of the sewer pipe", conf = "medium" },
}

