---------------------------------------------------------------------------
-- Load: the switches applied, then merged into DungeonMaps.lua's tables
---------------------------------------------------------------------------
for _, dm in pairs(ns.DUNGEON_MAPS_MM) do
    if not ANGLED_PAGES then
        -- (drop the angled floors; sub-zone names of later floors move down, names of dropped ones go)
        local keep, map = {}, {}
        for i, f in ipairs(dm.f) do
            if not f.rq then keep[#keep + 1] = f map[i] = #keep end
        end
        if #keep < #dm.f then
            dm.f = keep
            for name, fl in pairs(dm.s or {}) do dm.s[name] = map[fl] end
        end
    end
    for _, f in ipairs(dm.f) do
        local look = f.k and LOOKS[LOOK[f.k] or "raw"]
        if look then f.bg, f.st = look.bg, look.st end
    end
end
for id, dm in pairs(ns.DUNGEON_MAPS_MM) do ns.DUNGEON_MAPS[id] = dm end
for k, e in pairs(ns.DUNGEON_ENTRANCES_MM) do ns.DUNGEON_ENTRANCES[k] = e end
-- (review) the doors only on WoW Forever - Dungeon.lua's own build test: on Classic Era (11508 / 11509) these instances
-- do not exist, and Labels.lua would draw every ns.INSTANCES row on its world map (1.4.0: ns.FLAVOR, OneCopy.lua -
-- before 1.4.0 the interface number here, 16000 - 19999)
if ns.FLAVOR == "forever" then
    for _, door in ipairs(ns.FOREVER_DOORS) do
        local dm = ns.DUNGEON_MAPS[door.d]
        if dm and dm.f[door.floor or 1] and ns.INSTANCES and not ns.DUNGEON_ENTRANCES[door.label] then
            ns.INSTANCES[#ns.INSTANCES + 1] = { door.c, door.x, door.y, door.label, door.kind or "dungeon", zone = door.zone, door = door }
            ns.DUNGEON_ENTRANCES[door.label] = { d = { door.d }, floor = door.floor or 1, note = door.note }
        end
    end
end
